def classificar(leituras, limite):
    alertas = 0
    for x in leituras:
        if x > limite:
            alertas += 1
            if alertas > 3:
                break
        elif x < 0:
            continue
    while alertas > 0:
        alertas -= 1
        if alertas == 2:
            return "parcial"
    return "ok"
```

